const { useState } = React;

const SIDES = ["top", "right", "bottom", "left"];
// 写法 → 每条边取第几个值，与 margin / padding 的简写规则一致
const SYNTAX = {
  1: { map: [0, 0, 0, 0], labels: ["四边"] },
  2: { map: [0, 1, 0, 1], labels: ["上下", "左右"] },
  3: { map: [0, 1, 2, 1], labels: ["上", "左右", "下"] },
  4: { map: [0, 1, 2, 3], labels: ["上", "右", "下", "左"] },
};
const DOTS = ["bg-tag-1", "bg-tag-2", "bg-tag-3", "bg-tag-4"];
const TEXTS = ["text-tag-1", "text-tag-2", "text-tag-3", "text-tag-4"];
const MAX = 60;

// 容器边到盒子边的距离标尺，颜色与提供该值的滑块一致
const Guide = ({ side, value, index }) => {
  const vertical = side === "top" || side === "bottom";
  const position = {
    top: { top: 0, left: "50%", height: value },
    bottom: { bottom: 0, left: "50%", height: value },
    left: { left: 0, top: "50%", width: value },
    right: { right: 0, top: "50%", width: value },
  }[side];
  if (!value) return null;
  return (
    <div
      className={`pointer-events-none absolute flex items-center justify-center ${vertical ? "w-0.5 -translate-x-1/2" : "h-0.5 -translate-y-1/2"} ${DOTS[index]}`}
      style={position}
    >
      <span className={`absolute whitespace-nowrap rounded-full bg-surface px-1.5 font-tau-mono text-tau-tiny shadow-card ${TEXTS[index]} ${vertical ? "left-1.5" : "top-1.5"}`}>
        {value}px
      </span>
    </div>
  );
};

const Component = () => {
  const [count, setCount] = useState(4);
  const [values, setValues] = useState([10, 20, 30, 40]);
  const { map, labels } = SYNTAX[count];
  const resolved = map.map(index => values[index]);
  const shorthand = values.slice(0, count).map(value => `${value}px`).join(" ");

  const update = (index, value) => setValues(list => list.map((item, i) => (i === index ? value : item)));

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
          .cb-container {
            background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
            background-size: 16px 16px;
          }
        }
      `}</style>
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-tau-sm text-ink-3">写法</span>
        {[1, 2, 3, 4].map(value => (
          <button
            key={value}
            type="button"
            aria-pressed={count === value}
            onClick={() => setCount(value)}
            className={`cursor-pointer rounded-full border px-3 py-1 text-tau-sm transition-colors ${
              count === value ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {value} 值
          </button>
        ))}
      </div>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="cb-container relative h-[240px] min-w-0 rounded-tau-md border border-dashed border-line-1">
          <span className="absolute bottom-1.5 left-2 font-tau-mono text-tau-tiny text-ink-3">position: relative</span>
          {SIDES.map((side, i) => (
            <Guide key={side} side={side} value={resolved[i]} index={map[i]} />
          ))}
          <div
            className="absolute grid place-items-center rounded-tau-sm border border-accent bg-accent-soft transition-[inset] duration-200 ease-tau-out"
            style={{ inset: resolved.map(value => `${value}px`).join(" ") }}
          >
            <span className="font-tau-mono text-tau-sm text-accent-text">position: absolute</span>
          </div>
        </div>
        <div className="flex flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          {labels.map((label, index) => (
            <label key={label} className="flex items-center gap-3">
              <span className={`size-2 shrink-0 rounded-full ${DOTS[index]}`} />
              <span className="w-8 shrink-0 text-tau-sm text-ink-2">{label}</span>
              <input
                type="range"
                min={0}
                max={MAX}
                value={values[index]}
                onChange={event => update(index, Number(event.target.value))}
                className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
              />
              <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{values[index]}px</span>
            </label>
          ))}
          <div className="flex flex-col gap-1 rounded-tau-sm bg-hover px-3 py-2 font-tau-mono text-tau-sm">
            <span className="min-w-0 break-all text-ink-1">inset: {shorthand};</span>
            <span className="text-tau-tiny text-ink-3">等价于</span>
            {SIDES.map((side, i) => (
              <span key={side} className="flex items-center gap-2 text-ink-2">
                <span className={`size-1.5 shrink-0 rounded-full ${DOTS[map[i]]}`} />
                {side}: {resolved[i]}px;
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

