const { useState } = React;

const IMAGE = "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-9d3181_bd5ad183-67ed-42b1-bd31-6eea57e3388d.webp";
const SIDES = [
  { key: "top", label: "上" },
  { key: "right", label: "右" },
  { key: "bottom", label: "下" },
  { key: "left", label: "左" },
];
const PRESETS = [
  { label: "单值", value: { top: 12, right: 12, bottom: 12, left: 12, rx: 0, ry: 0 } },
  { label: "四边不同", value: { top: 10, right: 20, bottom: 30, left: 40, rx: 0, ry: 0 } },
  { label: "加圆角", value: { top: 10, right: 15, bottom: 10, left: 15, rx: 16, ry: 16 } },
  { label: "椭圆圆角", value: { top: 10, right: 15, bottom: 10, left: 15, rx: 48, ry: 16 } },
];

// 与 margin 一样把四个偏移压缩成最短写法
const compact = ([top, right, bottom, left]) => {
  if (left === right) {
    if (top === bottom) return top === right ? [top] : [top, right];
    return [top, right, bottom];
  }
  return [top, right, bottom, left];
};

const Slider = ({ label, value, max, unit, onChange }) => (
  <label className="flex items-center gap-3">
    <span className="w-6 shrink-0 text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={0}
      max={max}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-11 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">
      {value}
      {unit}
    </span>
  </label>
);

const Component = () => {
  const [shape, setShape] = useState(PRESETS[2].value);
  const [ghost, setGhost] = useState(true);
  const set = key => value => setShape(current => ({ ...current, [key]: value }));

  const offsets = compact(SIDES.map(side => shape[side.key])).map(value => `${value}%`).join(" ");
  const round = shape.rx || shape.ry ? ` round ${shape.rx === shape.ry ? `${shape.rx}px` : `${shape.rx}px / ${shape.ry}px`}` : "";
  const clipValue = `inset(${offsets}${round})`;
  const outline = {
    top: `${shape.top}%`,
    right: `${shape.right}%`,
    bottom: `${shape.bottom}%`,
    left: `${shape.left}%`,
    borderRadius: `${shape.rx}px / ${shape.ry}px`,
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative h-[240px] min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          {ghost && <div className="absolute inset-0 bg-cover bg-center opacity-25" style={{ backgroundImage: `url("${IMAGE}")` }} />}
          <div
            className="absolute inset-0 bg-cover bg-center transition-[clip-path] duration-200 ease-tau-out"
            style={{ backgroundImage: `url("${IMAGE}")`, clipPath: clipValue }}
          />
          <div className="pointer-events-none absolute border-2 border-dashed border-accent transition-all duration-200 ease-tau-out" style={outline} />
        </div>
        <div className="flex flex-col gap-2.5 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">偏移（参考框向内收缩）</span>
          {SIDES.map(side => (
            <Slider key={side.key} label={side.label} value={shape[side.key]} max={45} unit="%" onChange={set(side.key)} />
          ))}
          <span className="pt-1 text-tau-sm text-ink-3">round 圆角</span>
          <Slider label="水平" value={shape.rx} max={60} unit="px" onChange={set("rx")} />
          <Slider label="垂直" value={shape.ry} max={60} unit="px" onChange={set("ry")} />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {PRESETS.map(preset => (
          <ui.Button key={preset.label} variant="secondary" size="sm" onClick={() => setShape(preset.value)}>
            {preset.label}
          </ui.Button>
        ))}
        <div className="ml-auto">
          <ui.Switch checked={ghost} onCheckedChange={setGhost} label="显示被裁掉的部分" size="sm" />
        </div>
      </div>
      <code className="min-w-0 break-all rounded-tau-sm bg-hover px-2 py-1.5 font-tau-mono text-tau-sm text-ink-2">
        clip-path: {clipValue};
      </code>
    </div>
  );
};
